    $pdo=tamiran_db();$scope=v2_scope();$method=$_SERVER['REQUEST_METHOD']??'GET';
    if($method==='GET'){
        $public=v2_text($_GET['id']??'','فایل',80);$statement=$pdo->prepare('SELECT * FROM tamiran_private_files WHERE public_id=:public AND shop_id=:shop AND branch_id=:branch LIMIT 1');$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$file=$statement->fetch();if(!is_array($file))throw new TamiranApiException('فایل پیدا نشد.',404);if(in_array($file['purpose'],['identity','signature'],true)&&!in_array($scope['role'],['repair_manager','reception'],true))throw new TamiranApiException('مشاهده مدرک هویتی مجاز نیست.',403);$path=tamiran_private_root().'/files/'.$file['storage_key'];$real=realpath($path);$root=realpath(tamiran_private_root().'/files');if(!is_string($real)||!is_string($root)||!str_starts_with($real,$root.DIRECTORY_SEPARATOR)||!is_file($real))throw new TamiranApiException('فایل ذخیره‌شده در دسترس نیست.',404);header('Content-Type: '.$file['mime_type']);header('Content-Length: '.filesize($real));header('Content-Disposition: inline; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',basename((string)$file['original_name'])).'"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');readfile($real);exit;
